{
  "outcome": "candidates",
  "summary": "Discovered one RECAP terminal-fragment candidate and saved the detailed record to candidate-discovery.json. No package was authored.",
  "saved_candidates": [],
  "candidates": [
    {
      "name": "rdkit-recap-terminal-fragments",
      "capability": "Extract unique terminal molecular fragment SMILES using RDKit RecapDecompose and GetLeaves, preserving attachment markers and valid empty results.",
      "boundary": "Default RDKit RECAP fragmentation of valid molecular SMILES. Terminal descendants exclude the root and intermediate nodes. Results describe unique fragments, not multiplicities, descriptors, or validated synthetic feasibility. Proposed wrapper boundaries reject blank, non-string, unparseable, and zero-atom inputs separately from successful empty results.",
      "value": "Resolves the distinction between immediate children, all descendants, and terminal fragments, and prevents treating valid empty results as failures or returning the original molecule as a fragment.",
      "usage_path": "Chem.MolFromSmiles(input) → validate molecule → Recap.RecapDecompose(mol) → root.GetLeaves() → sorted leaf SMILES keys. Mapping values expose .mol. Use fresh per-input state and default settings. The later author-stage entry is prebound to scripts/terminal_fragments.py.",
      "construction": "Direct packaging of existing RDKit APIs with parsing, validation, sorting, and serialization glue. Later delivery should document Python/RDKit prerequisites, input boundaries, result semantics, and source attribution. Business execution is permitted only inside Docker. No runtime files were created during discovery.",
      "evidence": [
        {
          "id": "e1",
          "claim": "Inspected document.py, lines 31-56: the overview identifies RECAP and states 'To get the standard set of RECAP results, use GetLeaves()'. Its example distinguishes four immediate children, five descendants, and three terminal fragments; leaf values expose .mol."
        },
        {
          "id": "e1",
          "claim": "document.py, lines 97-118 and 134-138: GetLeaves returns a SMILES-keyed dictionary of terminal descendants, traversing children only. A root without children returns an empty dictionary; the root is not included."
        },
        {
          "id": "e1",
          "claim": "document.py, lines 146-169 and 185-213: RecapDecompose accepts a molecule, immediately converts it to SMILES, defaults to minFragmentSize=0 and onlyUseReactions=None, and constructs SMILES-keyed nodes. It supplies no explicit invalid-SMILES validation layer."
        },
        {
          "id": "e1",
          "claim": "document.py, lines 186-195 and test2 at 231-235: default product filtering can leave valid CCCOCCC with no children, establishing a valid empty GetLeaves result. testMinFragmentSize at 279-293 shows that changing minFragmentSize to 3 instead yields one unique terminal fragment, *CCC."
        },
        {
          "id": "e1",
          "claim": "document.py, lines 63-86: the implementation requires RDKit Chem and rdChemReactions and introduces * dummy atoms through reaction definitions. Lines 81-82 identify one rule as outside the standard RECAP set, so claims should concern this RDKit implementation."
        },
        {
          "id": "e2",
          "claim": "Inspected document.txt: BSD redistribution conditions 1-3 require notices and prohibit unauthorized endorsement; the final disclaimer provides the software AS IS. document.py lines 2-29 additionally contain the module's Novartis copyright and conditions."
        }
      ],
      "gaps": [
        "Runtime behavior remains untested; subsequent molecular checks must run only in an approved Docker container.",
        "Malformed and blank SMILES parser behavior is not documented in the supplied module; proposed rejection rules are wrapper safeguards.",
        "Disconnected inputs and unusual chemical or stereochemical cases are not characterized by the inspected passages."
      ],
      "blocked": false
    }
  ],
  "omitted": [
    {
      "capability": "Full hierarchy export and shared fragment networks",
      "reason": "Beyond terminal-fragment scope; necessary hierarchy interpretation is included in the candidate."
    },
    {
      "capability": "Custom reaction subsets and fragment-size policies",
      "reason": "They change output semantics and are unnecessary for the requested default workflow."
    },
    {
      "capability": "Descriptors and chemical validation",
      "reason": "Unsupported by this fragmentation source."
    }
  ],
  "limitations": [
    "The original research paper was not inspected; findings concern the supplied pinned implementation and relevant embedded tests.",
    "The helper's configured Python executable was unavailable. Native PowerShell saved candidate-discovery.json; no helper-registered candidate is selected.",
    "No installation, molecular execution, package authoring, or finish call occurred."
  ]
}
